from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]

def rule(i,title,kinds,field,fail,severity,domain,desc,rem,framework,fix=None,**extra):
    return dict(id=i,title=title,kinds=kinds,field=field,operator=extra.pop('operator', 'equals'),fail_value=fail,severity=severity,domain=domain,
                description=desc,remediation=rem,framework=framework,fix=fix,**extra)
R=[]
R.append(rule('STO001','Storage permits anonymous reads',['storage'],'public_access',True,.85,'Configuration','A collected policy or public ACL permits anonymous reads. Effective access still depends on surrounding controls.','Remove anonymous grants and validate application access using a nonprivileged principal.',['NIST80053:AC-3','NISTCSF:PR.AA'],{'field':'public_access','value':False},techniques=['T1530']))
R.append(rule('STO002','Storage encryption is disabled',['storage'],'encryption_enabled',False,.7,'Configuration','At-rest encryption is explicitly disabled in the supplied evidence. A missing setting is unknown, not disabled.','Enable provider encryption; separately evaluate key ownership and rotation requirements.',['NIST80053:SC-28','NISTCSF:PR.DS'],{'field':'encryption_enabled','value':True}))
R.append(rule('STO003','Storage access logging is disabled',['storage'],'logging_enabled',False,.45,'Compliance evidence','The inspected access logging channel is disabled. Other audit channels may exist and require separate verification.','Enable the appropriate access audit channel with retention and least-privilege log storage.',['NIST80053:AU-12','NISTCSF:DE.CM'],{'field':'logging_enabled','value':True}))
R.append(rule('STO004','Storage transport protection is absent',['storage'],'secure_transport',False,.65,'Configuration','Evidence explicitly indicates that HTTPS transport is not enforced.','Enforce HTTPS and minimum TLS requirements after compatibility testing.',['NIST80053:SC-8','NISTCSF:PR.DS'],{'field':'secure_transport','value':True}))
R.append(rule('STO005','Storage permits anonymous access configuration',['storage'],'anonymous_disabled',False,.5,'Configuration','The account can permit public containers. This setting alone does not prove an anonymously readable container.','Disable account-level anonymous access where public content is not an approved requirement.',['NIST80053:AC-3','NISTCSF:PR.AA'],{'field':'anonymous_disabled','value':True}))
R.append(rule('NET001','Network has a broad inbound administration rule',['network'],'admin_open',True,.8,'Exposure','An enabled inbound rule permits Internet-wide SSH or RDP. Routing, instance binding and higher-priority denies determine actual reachability.','Restrict sources to approved administration networks or use a bastion. Validate effective routes and rules.',['NIST80053:SC-7','NISTCSF:PR.IR'],{'field':'admin_open','value':False},techniques=['T1133']))
R.append(rule('IAM001','Identity has a broad privilege grant',['identity'],'broad_privilege',True,.85,'Identity','A broad grant is present. Boundaries, denies, conditions and resource policies can restrict effective authorization.','Review the grant, scope and dependencies; reduce privileges only after owner approval and operational tests.',['NIST80053:AC-6','NISTCSF:PR.AA'],{'field':'broad_privilege','value':False},techniques=['T1078.004']))
R.append(rule('IAM002','Console user has no registered MFA device',['identity'],'mfa_enabled',False,.8,'Identity','A console-enabled user has no registered MFA device in the inspected IAM API. Federation and conditional access require separate checks.','Require approved MFA or use federation; verify enforcement rather than relying only on device registration.',['NIST80053:IA-2','NISTCSF:PR.AA'],{'field':'mfa_enabled','value':True},when={'console_enabled':True}))
R.append(rule('IAM003','Identity has no observed activity for over 90 days',['identity'],'days_inactive',90,.45,'Identity','A complete declared telemetry window contains no activity for over 90 days. This is a review candidate, not proof of unnecessary access.','Check seasonal, recovery and automation duties, missing data-plane logs and ownership before changing access.',['NIST80053:AC-2','NISTCSF:PR.AA'],operator='greater'))
R.append(rule('WRK001','Workload has an exploitable vulnerability signal',['workload'],'exploitable',True,.9,'Workload','A native or imported vulnerability assessment marks an exploitable condition. CVSS is used only if supplied.','Patch or isolate after testing; confirm asset mapping and rescan to validate the fix.',['NIST80053:SI-2','NISTCSF:PR.PS'],{'field':'exploitable','value':False},techniques=['T1190']))
R.append(rule('WRK002','Workload security monitoring is disabled',['workload'],'monitoring_enabled',False,.6,'Workload','The collected signal explicitly reports missing workload monitoring. This project does not deploy a runtime agent.','Enable workload protection and validate detection events and coverage.',['NIST80053:SI-4','NISTCSF:DE.CM'],{'field':'monitoring_enabled','value':True}))
R.append(rule('EXP001','Workload is reachable from the Internet',['workload'],'internet_reachable',True,.55,'Exposure','A supplied reachability assessment asserts Internet access. A public IP alone is not accepted as this assertion.','Reduce reachability using approved ingress, private endpoints or tested segmentation.',['NIST80053:SC-7','NISTCSF:PR.IR'],{'field':'internet_reachable','value':False}))
R.append(rule('K8S001','Cluster-admin role bound to an unauthenticated or over-privileged group',['kubernetes'],'k8s_admin_exposed',True,.85,'Configuration','Cluster-admin role bound to an unauthenticated or over-privileged group; permits broad workload compromise within a Kubernetes environment.','Restrict cluster-admin bindings to trusted users.',['NIST80053:AC-6','NISTCSF:PR.AA'],{'field':'k8s_admin_exposed','value':False}))
R.append(rule('K8S002','Missing network policies allowing unrestricted pod-to-pod communication',['kubernetes'],'k8s_netpol_missing',True,.65,'Configuration','Missing network policies allowing unrestricted pod-to-pod communication; facilitates lateral movement, though exploitability depends on network topology.','Implement default-deny network policies.',['NIST80053:SC-7','NISTCSF:PR.AC'],{'field':'k8s_netpol_missing','value':False}))
R.append(rule('DB001','Missing at-rest encryption for a graph database or relational instance',['database'],'encryption_enabled',False,.7,'Configuration','Missing at-rest encryption for a graph database or relational instance; loss of confidentiality upon underlying volume compromise without establishing direct network exposure.','Enable at-rest encryption on database volumes.',['NIST80053:SC-28','NISTCSF:PR.DS'],{'field':'encryption_enabled','value':True}))
R.append(rule('DSPM001','Unclassified or unconsented PII discovered in unmanaged storage',['storage'],'unmanaged_pii',True,.9,'Data Security','Unclassified or unconsented Personal Identifiable Information (PII) discovered in unmanaged storage; severe regulatory impact depending on data sensitivity mapping.','Classify and secure PII using DSPM controls.',['NIST80053:PE-19','NISTCSF:PR.DS'],{'field':'unmanaged_pii','value':False}))
R.append(rule('SEC001','Missing or misconfigured continuous vulnerability telemetry agent',['workload'],'telemetry_agent_active',False,.6,'Monitoring','Missing or misconfigured continuous vulnerability telemetry agent (e.g., Defender or Wazuh); represents a security monitoring gap rather than a direct exploit path.','Deploy and verify security telemetry agents.',['NIST80053:SI-4','NISTCSF:DE.CM'],{'field':'telemetry_agent_active','value':True}))
# Preserve the reviewed per-control severity explanation on fixture regeneration.
existing=ROOT/'config/policies.json'
if existing.exists():
    reviewed={r['id']:r.get('severity_basis','Author policy anchor; review risk methodology') for r in json.loads(existing.read_text())['rules']}
    for r in R:r['severity_basis']=reviewed.get(r['id'],'Author policy anchor; review risk methodology')
(ROOT/'config/policies.json').write_text(json.dumps({'version':'policy-priority-v1','weights':{'severity':.30,'exposure':.20,'exploitability':.20,'impact':.20,'path':.10},'rules':R},indent=2))
resources=[];edges=[]
def add(p,id,name,kind,a):
    r={'id':f'{p}:{id}','name':name,'provider':p,'account':{'aws':'111122223333','azure':'demo-subscription','gcp':'demo-project'}[p],
       'kind':kind,'observed_at':'2026-10-07T00:00:00+00:00','source':'synthetic scenario fixture','attributes':a}
    resources.append(r);return r['id']
for p in ('aws','azure','gcp'):
    workload=add(p,'web','payments-api' if p=='aws' else ('customer-api' if p=='azure' else 'analytics-api'),'workload',dict(internet_reachable=True,exploitable=True,cvss=9.8,kev=True,monitoring_enabled=False,criticality=.9,sensitivity=.8))
    identity=add(p,'service','application-service-identity','identity',dict(broad_privilege=True,console_enabled=False,mfa_enabled=None,days_inactive=None,criticality=.9,sensitivity=.8,exploitable=False,kev=False,internet_reachable=False))
    data=add(p,'data','regulated-customer-data','storage',dict(public_access=False,encryption_enabled=True,logging_enabled=False,secure_transport=True,anonymous_disabled=True,criticality=1.,sensitivity=1.,internet_reachable=False,exploitable=False,kev=False))
    add(p,'public','public-export-archive','storage',dict(public_access=True,encryption_enabled=True,logging_enabled=False,secure_transport=False,anonymous_disabled=False,criticality=.8,sensitivity=.9,exploitable=False,kev=False))
    add(p,'sg','legacy-admin-ingress','network',dict(admin_open=True,internet_reachable=None,criticality=.7,sensitivity=.4,exploitable=False,kev=False))
    add(p,'user','dormant-contractor','identity',dict(broad_privilege=True,console_enabled=True,mfa_enabled=False,days_inactive=124,telemetry_complete=True,internet_reachable=False,criticality=.6,sensitivity=.6,exploitable=False,kev=False))
    add(p,'private','internal-build-worker','workload',dict(internet_reachable=False,exploitable=False,monitoring_enabled=True,criticality=.3,sensitivity=.2,kev=False))
    add(p,'unknown','unobserved-research-bucket','storage',dict(public_access=None,encryption_enabled=None,logging_enabled=None,secure_transport=None,anonymous_disabled=None,criticality=None,sensitivity=None))
    edges.extend([{'from':workload,'to':identity,'type':'runs_as','verified':True,'evidence':'Synthetic workload identity binding; scenario manifest v1'},
                  {'from':identity,'to':data,'type':'can_read','verified':True,'evidence':'Synthetic effective read grant; scenario manifest v1'}])
s={'schema_version':'1.0','source':'demo','resources':resources,'edges':edges,
   'connectors':[{'provider':p,'status':'demo','detail':'Synthetic evidence. No cloud API was called.'} for p in ('aws','azure','gcp')]}
(ROOT/'fixtures/demo.json').write_text(json.dumps(s,indent=2))
(ROOT/'fixtures/import.example.json').write_text(json.dumps({**s,'source':'import'},indent=2))
print(f'Created {len(R)} controls, {len(resources)} resources and {len(edges)} verified scenario edges')
